From 59e2513945c348a81dd1a4ed8729d61debc3eea2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:24:28 +0100
Subject: [PATCH] applets/pager: Keep horizontal scrolling within the current
 row

On a pager with several rows, scrolling sideways stepped through all
desktops and jumped to the next row, even with wrapping off. Keep it in
the current row; vertical scrolling still reaches every desktop.

BUG: 471160
---
 applets/pager/qml/main.qml | 22 ++++++++++++++--------
 1 file changed, 14 insertions(+), 8 deletions(-)

diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..4f02426044 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -114,21 +114,27 @@ PlasmoidItem {
                 increment--;
             }

+            // Horizontal scrolling moves within the current row
+            const rowLength = wheel.angleDelta.y ? repeater.count : pagerItemGrid.columns;
+            const rowStart = pagerModel.currentPage - pagerModel.currentPage % rowLength;
+            const count = Math.min(rowLength, repeater.count - rowStart);
+            const current = pagerModel.currentPage - rowStart;
+
             while (increment !== 0) {
                 if (increment < 0) {
                     const nextPage = Plasmoid.configuration.wrapPage?
-                        (pagerModel.currentPage + 1) % repeater.count :
-                        Math.min(pagerModel.currentPage + 1, repeater.count - 1);
+                        (current + 1) % count :
+                        Math.min(current + 1, count - 1);
                     // At the last desktop: changePage() on the current one would toggle Show Desktop
-                    if (nextPage !== pagerModel.currentPage) {
-                        pagerModel.changePage(nextPage);
+                    if (nextPage !== current) {
+                        pagerModel.changePage(rowStart + nextPage);
                     }
                 } else {
                     const previousPage = Plasmoid.configuration.wrapPage ?
-                        (repeater.count + pagerModel.currentPage - 1) % repeater.count :
-                        Math.max(pagerModel.currentPage - 1, 0);
-                    if (previousPage !== pagerModel.currentPage) {
-                        pagerModel.changePage(previousPage);
+                        (count + current - 1) % count :
+                        Math.max(current - 1, 0);
+                    if (previousPage !== current) {
+                        pagerModel.changePage(rowStart + previousPage);
                     }
                 }

-- 
